/**
 * Guard responsible for protecting leaving page with unsaved changes.
 */
class UnsavedChangesGuard {
    constructor() {
        this.dialog = inject(MatDialog);
        this.authenticationService = inject(AuthenticationService);
        this.authGuardBaseService = inject(AuthGuardService);
        this.unsaved = false;
    }
    /**
     * Allows to deactivate route when there is no unsaved changes, otherwise displays dialog to confirm discarding changes.
     *
     * @returns boolean | Observable<boolean> true when there is no unsaved changes or changes can be discarded, false otherwise.
     */
    canDeactivate() {
        if (!this.authenticationService.isLoggedIn() && !this.authGuardBaseService.withCredentials) {
            return of(true);
        }
        return this.unsaved
            ? this.dialog
                .open(UnsavedChangesDialogComponent, {
                maxWidth: this.data?.maxWidth ?? 346,
                data: this.data
            })
                .afterClosed()
                .pipe(tap((confirmed) => (this.unsaved = !confirmed)), map((confirmed) => !!confirmed))
            : true;
    }
    static { this.ɵfac = i0.ɵɵngDeclareFactory({ minVersion: "12.0.0", version: "20.3.25", ngImport: i0, type: UnsavedChangesGuard, deps: [], target: i0.ɵɵFactoryTarget.Injectable }); }
    static { this.ɵprov = i0.ɵɵngDeclareInjectable({ minVersion: "12.0.0", version: "20.3.25", ngImport: i0, type: UnsavedChangesGuard, providedIn: 'root' }); }
}
